function R = CBF_DIAGNOSE_BODYRATE_STEP(snapshotFile)
% CBF_DIAGNOSE_BODYRATE_STEP
% Diagnose the anomalous body-rate change over the last accepted physical-CBF
% step. Read-only: does not change the HLC, plant, estimator, CBF or QP.
%
% Usage:
%   R = CBF_DIAGNOSE_BODYRATE_STEP('CBF_physical_QP_failure.mat');
%
% Required snapshot is generated by Generate_CBF_ActuatorAware_6Methods.
% "actual" means *estimator output* D.x, NOT the true plant state.
% The command prev.uSafe may have been changed by input_transform/actuators;
% the true applied torque cannot be recovered from this snapshot alone.
if nargin < 1 || isempty(snapshotFile)
    snapshotFile = 'CBF_physical_QP_failure.mat';
end
if ~isfile(snapshotFile)
    error('CBF:Audit:NoFile','Snapshot not found: %s',snapshotFile);
end
S = load(snapshotFile);
if ~isfield(S,'D') || ~isfield(S.D,'supervisor') || ...
        ~isfield(S.D.supervisor,'lastActiveTrace') || ...
        isempty(S.D.supervisor.lastActiveTrace)
    error('CBF:Audit:NoTrace', ...
        'Snapshot requires D.supervisor.lastActiveTrace from a prior accepted QP.');
end
D=S.D;
T=D.supervisor.lastActiveTrace;
if ~all(isfield(T,{'x','time','uSafe','auxBefore','auxAfter','w'}))
    error('CBF:Audit:TraceFields','Previous accepted trace lacks required fields.');
end
if ~all(isfield(D,{'x','P','time','dt'}))
    error('CBF:Audit:SnapshotFields','Snapshot lacks x/P/time/dt.');
end
x0=T.x(:); x1=D.x(:); P=D.P(:); M=T.uSafe(2:4); J=P(2:4);
w0=x0(5:7); w1=x1(5:7); dt=D.dt;
if numel(x0)~=19 || numel(x1)~=19 || numel(P)~=9 || ...
        numel(J)~=3 || any(~isfinite([x0;x1;P;M])) || ...
        any(J<=0) || dt<=0
    error('CBF:Audit:InvalidState','Nonfinite, invalid-size or nonpositive inertia/time.');
end
q0=x0(1:4); q1=x1(1:4);
R=struct();
R.timeStart=T.time; R.timeEnd=D.time; R.dt=dt;
R.estimatedLoadmassCurrent=P(6);
R.J=J; R.Mcommand=M; R.wPrevious=w0;R.wCurrentEstimator=w1;
R.wDeltaMeasured=w1-w0;
R.wDotMeasured=(w1-w0)/dt;
R.wDotPredicted=(M-cross(w0,J.*w0))./J;
R.wEuler=w0+dt*R.wDotPredicted;
opts=odeset('RelTol',1e-11,'AbsTol',1e-12);
[~,Y]=ode45(@(t,w) localEulerRate(w,M,J),[0 dt],w0,opts);
R.wODE=Y(end,:)';
[~,Y0]=ode45(@(t,w) localEulerRate(w,zeros(3,1),J),[0 dt],w0,opts);
R.wZeroTorque=Y0(end,:)';
[~,Yn]=ode45(@(t,w) localEulerRate(w,-M,J),[0 dt],w0,opts);
R.wOppositeTorque=Yn(end,:)';
% First-order midpoint reconstruction of an equivalent *constant* torque.
% This is not a direct measurement and assumes the same inertia J, rigid-body
% equations and no unmodeled disturbance/estimator correction.
wmid=(w0+w1)/2;
R.MequivalentApprox=J.*((w1-w0)/dt)+cross(wmid,J.*wmid);
R.MdifferenceApprox=R.MequivalentApprox-M;
R.estimatedOmegaResidual=norm(R.wODE-w1);
R.estimatedOmegaResidualNoTorque=norm(R.wZeroTorque-w1);
R.estimatedOmegaResidualOpposite=norm(R.wOppositeTorque-w1);
R.eulerVsODE=norm(R.wEuler-R.wODE);
R.qNorms=[norm(q0),norm(q1)];
if all(R.qNorms>1e-12)
    qa=q0/norm(q0);qb=q1/norm(q1);
    R.estimatedQuaternionStepAngleRad=2*acos(min(1,abs(dot(qa,qb))));
else
    R.estimatedQuaternionStepAngleRad=NaN;
end
R.nominalAngleFromWApprox=dt*norm(wmid);
R.torqueWithinAssumedBounds=all(abs(M)<=1+1e-9);
R.stepCount=(D.time-T.time)/dt;

fprintf('\n=== PHYSICAL CBF BODY-RATE AUDIT (READ ONLY) ===\n');
fprintf('t=%.6f -> %.6f, dt=%.6f, steps=%.6f\n',T.time,D.time,dt,R.stepCount);
fprintf('J=[%.9g %.9g %.9g] kg m^2, mL_est(current)=%.9g kg\n',J,P(6));
fprintf('CBF requested M=[%+.9g %+.9g %+.9g] N m; |M|<=1: %d\n', ...
    M,R.torqueWithinAssumedBounds);
fprintf('omega(k)      = [%+.9g %+.9g %+.9g] rad/s\n',w0);
fprintf('omega(k+1) EKF= [%+.9g %+.9g %+.9g] rad/s\n',w1);
fprintf('omega predicted ODE with commanded M=[%+.9g %+.9g %+.9g]\n',R.wODE);
fprintf('omega predicted Euler (1 step)   =[%+.9g %+.9g %+.9g]\n',R.wEuler);
fprintf('omega predicted with M=0         =[%+.9g %+.9g %+.9g]\n',R.wZeroTorque);
fprintf('omega predicted with -M          =[%+.9g %+.9g %+.9g]\n',R.wOppositeTorque);
fprintf('omega error commanded=%.9g | zero=%.9g | opposite=%.9g rad/s\n', ...
    R.estimatedOmegaResidual,R.estimatedOmegaResidualNoTorque, ...
    R.estimatedOmegaResidualOpposite);
fprintf('Euler-vs-ODE integration difference=%.9g rad/s\n',R.eulerVsODE);
fprintf('observed omegaDot(EKF finite difference)=[%+.9g %+.9g %+.9g] rad/s^2\n',R.wDotMeasured);
fprintf('modeled omegaDot initial         =[%+.9g %+.9g %+.9g] rad/s^2\n',R.wDotPredicted);
fprintf('equivalent mean torque APPROX    =[%+.9g %+.9g %+.9g] N m\n',R.MequivalentApprox);
fprintf('equivalent - requested M APPROX  =[%+.9g %+.9g %+.9g] N m\n',R.MdifferenceApprox);
fprintf('estimated quaternion change=%.9g rad; dt*norm(mid omega)=%.9g rad\n', ...
    R.estimatedQuaternionStepAngleRad,R.nominalAngleFromWApprox);
fprintf('Previous/current quaternion norms: %.8g / %.8g\n',R.qNorms);
if abs(R.stepCount-1)>1e-3
    fprintf(2,'WARNING: snapshot times are NOT one control period apart.\n');
end
fprintf(['NOTE: These results alone CANNOT identify whether the mismatch is ' ...
    'input_transform/plant mapping, different inertia, or EKF correction.\n']);
fprintf(['NOTE: Varying estimated load mass is intentional; mL is not in the ' ...
    'rigid-body omegaDot equation above.\n']);
fprintf(['NEXT: compare actual plant omega and ACTUALLY APPLIED torque ' ...
    'on the same step; inspect Model_Suspended_Load and input_transform.\n']);
end

function wd=localEulerRate(w,M,J)
w=w(:);M=M(:);J=J(:);
wd=(M-cross(w,J.*w))./J;
end
